# Generated by 2sc from function 'gdbooster'.
# This command is intentionally Pro-only: the Docker backup is the sole source.
if (-not (Get-Command -Name 'Initialize-CodexProfileFunctions' -CommandType Function -ErrorAction SilentlyContinue)) {
    $__profileModule = Join-Path ([Environment]::GetFolderPath('UserProfile')) 'Documents\WindowsPowerShell\Modules\CodexProfileFunctions\CodexProfileFunctions.psd1'
    if (-not (Test-Path -LiteralPath $__profileModule -PathType Leaf)) {
        throw "gdbooster requires the Codex profile module: $__profileModule"
    }
    Import-Module -Name $__profileModule -DisableNameChecking -ErrorAction Stop
    Initialize-CodexProfileFunctions
}

function gdbooster {
    [CmdletBinding()]
    param([switch]$SelfTest)

    $appName = 'driverbooster'
    $target = 'F:\backup\windowsapps\installed\driverbooster'
    $restoreCommand = Get-Command -Name 'Invoke-BackupDockerInstalledAppRestore' -CommandType Function -ErrorAction SilentlyContinue
    if (-not $restoreCommand -or -not $restoreCommand.Parameters.ContainsKey('RequirePro')) {
        throw 'gdbooster requires the Pro-only Docker restore helper.'
    }
    if ($SelfTest) {
        $imageRef = Get-BackupDockerLatestImageRef -Name $appName
        if ($imageRef -notmatch '(?i)windowsapps-installed-driverbooster') { throw "gdbooster resolved an unexpected image: $imageRef" }
        Write-Host 'GDBOOSTER_SELFTEST_OK source=docker-container edition=pro fallbackInstaller=false' -ForegroundColor Green
        return
    }

    $startedAt = Get-Date
    Get-Process -Name 'DriverBooster' -ErrorAction SilentlyContinue | Stop-Process -Force
    Write-Host 'GDBOOSTER_PROGRESS stage=restoring-pro source=docker-container edition=pro' -ForegroundColor Cyan
    Invoke-BackupDockerInstalledAppRestore -Name $appName -RequirePro
    $exe = Get-ChildItem -LiteralPath $target -Filter 'DriverBooster.exe' -File -Recurse -Force -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $exe) { throw "gdbooster Pro restore completed but DriverBooster.exe is missing under $target" }
    $elapsedMs = [int]((Get-Date) - $startedAt).TotalMilliseconds
    Write-Host "GDBOOSTER_OK edition=pro source=docker-container path=$($exe.FullName) elapsed_ms=$elapsedMs" -ForegroundColor Green
}

if ($MyInvocation.InvocationName -ne '.') {
    & 'gdbooster' @args
}
